import math

def expression(n):
    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1
    return numerator / denominator

values = [5, 6, 7, 8]
results = {}
for n in values:
    value = expression(n)
    is_integer = value == int(value)
    results[n] = {'value': value, 'is_integer': is_integer}

print(results)

